/*START - Makes Global Font uppercase*/
h1{
    text-transform:uppercase!important;
}
.lp-h1{
    text-transform:uppercase!important;
}

h2{
    text-transform:uppercase!important;
}
.lp-h2{
    text-transform:uppercase!important;
}
h3{
    text-transform:uppercase!important;
}
.lp-h3{
text-transform:uppercase!important;
}

/*START - Sidemenu & header nav font */
div#global-sidemenu.sidemenu,nav#global-navbar{
    & a{
        text-transform:uppercase;
    }
    & button{
        text-transform:uppercase;
    }
}
/*END - Sidemenu & header nav font*/

/*START - change footer background(dark & modern theme)*/
footer#global-footer{
    background: linear-gradient(rgba(0,0,0,1), rgba(0,0,0,0.4) ,rgba(0,0,0,1)),url(https://res.cloudinary.com/luxuryp/images/f_auto,q_auto/tdcitkokhpcvdat9mbuc/black)!important;
    background-repeat: no-repeat;
    background-size: cover; 
}
/*END - change footer background(dark & modern theme)*/

/*START - change footer background(light & bright theme)*/
footer#global-footer{
    background-image: linear-gradient(rgba(255,255,255,1),rgba(255,255,255,0.3),rgba(255,255,255,1)), url('https://res.cloudinary.com/luxuryp/images/w_960,c_limit,f_auto,q_auto/sywmlbzm5umbvhbc7aqc/marble-background')!important;
    background-repeat: no-repeat;
    background-size: cover;
}
/*END - change footer background(light & bright theme)*/


/*START - change footer background(traditional navy theme)*/
footer#global-footer{
    background-image: linear-gradient(rgba(1,30,62,1),rgba(1,30,62,0.7),rgba(1,30,62,1)), url('https://res.cloudinary.com/luxuryp/images/ijhwon2je6u5yyd6jp9d/traditional-navy')!important;
    background-repeat: no-repeat;
    background-size: cover;
}
/*END - change footer background(traditional navy theme)*/

/*START - change footer background(west coast coastal theme)*/
footer#global-footer{
    background-image: linear-gradient(rgba(255,255,255,1),rgba(255,255,255,0.5),rgba(255,255,255,1)), url('https://res.cloudinary.com/luxuryp/images/kypmoxmg1jcdistuplee/bg-wood-texture-2')!important;
    background-repeat: no-repeat;
    background-size: cover;
}
/*END - change footer background(west coast coastal theme)*/

/*START - change footer background(earth tones theme)*/
footer#global-footer{
    background-image: linear-gradient(rgba(255,255,255,1),rgba(255,255,255,0.8),rgba(255,255,255,1)), url('https://res.cloudinary.com/luxuryp/images/cmwoazygbyw1zbmn7ojz/element-bg-1-2')!important;
    background-repeat: no-repeat;
    background-size: cover;
}
/*END - change footer background(earth tones theme theme)*/

/*START - change footer background(Palm tree)*/
footer#global-footer {
    background-image: linear-gradient(rgba(255,255,255,0.8),rgba(255,255,255,0.6),rgba(255,255,255,0.6),rgba(255,255,255,0.6)),url(https://res.cloudinary.com/luxuryp/images/wrc1f6ff5cw33qxtnc1u/bg-3)!important;
    background-repeat: no-repeat;
    background-size: cover;
}
/*END - change footer background(Palm tree)*/

/*START -  disclaimer link*/
footer#global-footer {
    .redesign .link{
        font-size:14px;
        &:before {
        background-color: #cccccc;
        }
        &:after {
        background-color: #000;
        }
    }
    @media(max-width:768px){
        .redesign .link{
        font-weight:normal;
        font-size:14px;
        text-decoration: underline;
        white-space: normal!important;
            &:before {
            background-color: transparent;
            }
            &:after {
            background-color: transparent;
            }
        }
    }
}
/*END - disclaimer link*/

/*START - sticky nav bar*/
#global-navbar{
    transform: translateY(0px) scaleY(1)!important;
}
/*END- sticky nav bar*/

/*START - add watermak logo in side menu*/
div#global-sidemenu{
    & >div:first-of-type{
        background-image: url('');
        background-repeat:no-repeat;
        background-size: contain;
        background-position: center;  
    }
    /*start - use only this portion in masterpiece design*/
    div.sidemenu__wrapper{
        background-image: url('');
        background-repeat:no-repeat;
        background-size: contain;
        background-position: center;
    }
    /*end - use only this portion in masterpiece design*/
}
/*END - add watermak logo in side menu*/

/*START - Change Accordion tab theme*/
.accordion{
    .accordion-opener {
        border: 2px solid #928B90;
        background-color: #928B90;
        &:before {
            border-color: #fff;
        }
        &:hover{
            border: 2px solid #696367;
            background-color: #696367;
            &:before {
                border-color: #fff;
            }
        }
    }
    .accordion-content {
    color: #000;
    background-color: #f7f7f7!important;
    }
}
/*ENd - Change Accordion tab theme*/

/*START - reduce space between title and description*/
div.accordion.tabs div.accordion-content.tab-body.is-active,div.accordion.tabs .accordion-content.tab-body.is-active{
    padding-bottom: 55px;
    padding-top: 0px;
}
@media only screen and (min-width: 769px){
    .accordion-header.is-active {
        padding-bottom: 30px!important;
    }
}
/*END - reduce space between title and description*/

/*START - link underline*/
.agent-detail-section {
    a.lp-link{
        border-bottom: none;
        text-decoration: none;
        position: relative!important;
        line-height: 1.7;
        &:before, &:after{
            transition: 0.4s;
            text-decoration: none!important;
            line-height: 1;
            content: "";
            height: 1px;
            position: absolute!important;
            bottom: 0;
            left: 0;
        }
        &:before {
            width: 100%!important;
            background-color: #ddd!important;
        }
        &:after{
            width: 0%!important;
            background-color: #000!important; 
        }
        &:hover:after{
            width: 100%!important;
        }
    }
}
/*END - link underline*/

/*START - reduce container width*/
div.lp-container {
    max-width: 1100px;
}
/*END- reduce container width*/

/*START - increase container width*/
div.lp-container {
    max-width: 1200px;
    .lp-title-group {
        max-width: 981px;
    }
}

/*START - decrease header title on mobile view*/
@media only screen and (max-width: 560px){
     h2 {
        font-size: 26px!important;
    }
}
/*END - decrease header title on mobile view*/

/*START - change dropdown title*/
div.form-col:nth-child(5) label.visually-hidden{
    font-size: 0;
  &::before {
    content: 'Select Bedrooms';
    font-size: 14px;
  }
}
/*END- change dropdown title*/

/*START - change dropdown color*/
div.lp-container div.lp-form-group.custom-form__group div.uf-cus-sel-content {
    background-color: #f1f1f1!important;
    border: 1px solid #f1f1f1!important;
    color:#000;
    .uf-cus-sel-item:focus, .uf-cus-sel-item:hover {
        background-color:#002349!important;
        color:#fff!important;
    }
}
/*END - change dropdown color*/

/*START - add width in description */
div.custom-form__header {
    max-width: 786px;
}
/*END - SEntencecase description */

/*START - Adjust description's padding*/
p.cta-section__lead.lp-text--subtitle{
    margin-bottom: 30px;
}
/*END - Adjust description's padding*/

/*START - making the header title uppercase*/
.lp-h1{
  text-transform: uppercase;
}
/*END- making the header title uppercase*/

/*START - remove pagination line*/
div.lp-title-group{
    margin: 0;
}
div.collection{
    .btn-container{
    margin-top: 0;
    }
    .slick-dots button{
        display: none;
    }
}
/*END - remove pagination line*/

/*START - add opacity on hover state*/
.featured-neighborhoods-grid .items .item .item-wrapper{
    &:hover .overlay {
    background-color: rgba(0, 0, 0, 0.5);
    transition: .3s;
    }
    .overlay {
    background-color: rgba(0, 0, 0, 0.3);
    transition: .3s;
    }
}
/*ENd - add opacity on hover state*/

/*START - fix play button*/
button.lp-play{
    border-radius: 50px;
    background-color:#fff;
    &:before{
        background-color: transparent;
    }
    &:after{
            border-color: transparent transparent transparent #000;
    }
    &:hover{
        background-color:#f1f1f1;
            &:after{
                    border-color: transparent transparent transparent #000;
            }
    }
}
/*END - fix play button*/

/*START - slick arrow color*/
button.lp-arrow:hover{
    background-color: #fff;
    border-color:#fff;
    color: #000!important;
}
/*END - slick arrow  color*/

/*START - add theme to button*/
button.lp-play{
    background-color:#fff;
    color: #9E2432;
    &:hover{
        background-color:#dedede;
        color: #9E2432;
    }
}
